[[nodiscard]] bool detailStartsWith(const QString& detail, QStringView prefix) {
    return detail.startsWith(prefix, Qt::CaseInsensitive);
}

[[nodiscard]] std::optional<uint64_t> parseHexDetail(const QStringList& details,
                                                     QStringView prefix) {
    for (const auto& detail : details) {
        if (!detailStartsWith(detail, prefix)) {
            continue;
        }
        const qsizetype marker = detail.indexOf(QStringLiteral("0x"), 0, Qt::CaseInsensitive);
        if (marker < 0) {
            return std::nullopt;
        }
        bool ok = false;
        const uint64_t value = detail.sliced(marker + 2).trimmed().toULongLong(&ok, 16);
        if (ok) {
            return value;
        }
    }
    return std::nullopt;
}

[[nodiscard]] std::optional<uint64_t> parseDecimalDetail(const QStringList& details,
                                                         QStringView prefix) {
    for (const auto& detail : details) {
        if (!detailStartsWith(detail, prefix)) {
            continue;
        }
        const auto parts = detail.split(QChar(':'));
        if (parts.size() < kMinimumKeyValuePartCount) {
            return std::nullopt;
        }
        bool ok = false;
        const uint64_t value = parts.last().trimmed().toULongLong(&ok, 10);
        if (ok) {
            return value;
        }
    }
    return std::nullopt;
}

[[nodiscard]] bool hasDetailContaining(const QStringList& details, QStringView needle) {
    for (const auto& detail : details) {
        if (detail.contains(needle, Qt::CaseInsensitive)) {
            return true;
        }
    }
    return false;
}

[[nodiscard]] bool hasSnapshotMutationRisk(const QStringList& details) {
    for (const auto& detail : details) {
        // A populated snapshot-metadata tree OID alone is the normal state of
        // every Apple-formatted volume (the tree exists empty from mkfs);
        // mutation risk is signalled by actual snapshots, a pending revert,
        // or a most-recent-snapshot transaction.
        if (detail.contains(QStringLiteral("most recent snapshot XID"), Qt::CaseInsensitive) ||
            detail.contains(QStringLiteral("pending revert"), Qt::CaseInsensitive)) {
            return true;
        }

        const int snapshotCountAt =
            detail.indexOf(QStringLiteral("snapshots "), 0, Qt::CaseInsensitive);
        if (snapshotCountAt < 0) {
            continue;
        }
        const QString countText = detail.mid(snapshotCountAt + kApfsSnapshotCountPrefixLength)
                                      .section(QLatin1Char(','), 0, 0)
                                      .trimmed();
        bool ok = false;
        const uint64_t count = countText.toULongLong(&ok);
        if (ok && count > 0) {
            return true;
        }
    }
    return false;
}

[[nodiscard]] QString normalizedApfsTargetPath(QString path) {
    path = path.trimmed();
    path.replace(QLatin1Char('\\'), QLatin1Char('/'));
    while (path.contains(QStringLiteral("//"))) {
        path.replace(QStringLiteral("//"), QStringLiteral("/"));
    }
    if (path.isEmpty()) {
        return {};
    }
    if (!path.startsWith(QLatin1Char('/'))) {
        path.prepend(QLatin1Char('/'));
    }
    while (path.size() > 1 && path.endsWith(QLatin1Char('/'))) {
        path.chop(1);
    }
    return path;
}

[[nodiscard]] QString normalizedApfsVolumeName(QString name) {
    name = name.trimmed();
    name.replace(QChar(0), QLatin1Char(' '));
    return name;
}

[[nodiscard]] bool containsUnsafePathSegment(const QString& normalized_path) {
    for (const auto& part : normalized_path.split(QLatin1Char('/'), Qt::SkipEmptyParts)) {
        if (part == QStringLiteral(".") || part == QStringLiteral("..")) {
            return true;
        }
    }
    return false;
}

[[nodiscard]] bool containsUnsafeVolumeNameCharacter(const QString& name) {
    return name.contains(QLatin1Char('/')) || name.contains(QLatin1Char('\\')) ||
           name.contains(QLatin1Char(':'));
}

void writeLe16(QByteArray* bytes, qsizetype offset, uint16_t value) {
    qToLittleEndian<uint16_t>(value, reinterpret_cast<uchar*>(bytes->data() + offset));
}

void writeLe32(QByteArray* bytes, qsizetype offset, uint32_t value) {
    qToLittleEndian<uint32_t>(value, reinterpret_cast<uchar*>(bytes->data() + offset));
}

void writeLe64(QByteArray* bytes, qsizetype offset, uint64_t value) {
    qToLittleEndian<uint64_t>(value, reinterpret_cast<uchar*>(bytes->data() + offset));
}

uint16_t le16(const QByteArray& bytes, qsizetype offset) {
    if (offset < 0 || bytes.size() - offset < static_cast<qsizetype>(sizeof(uint16_t))) {
        return 0;
    }
    return qFromLittleEndian<uint16_t>(reinterpret_cast<const uchar*>(bytes.constData() + offset));
}

uint32_t le32(const QByteArray& bytes, qsizetype offset) {
    if (offset < 0 || bytes.size() - offset < static_cast<qsizetype>(sizeof(uint32_t))) {
        return 0;
    }
    return qFromLittleEndian<uint32_t>(reinterpret_cast<const uchar*>(bytes.constData() + offset));
}

uint64_t le64(const QByteArray& bytes, qsizetype offset) {
    if (offset < 0 || bytes.size() - offset < static_cast<qsizetype>(sizeof(uint64_t))) {
        return 0;
    }
    return qFromLittleEndian<uint64_t>(reinterpret_cast<const uchar*>(bytes.constData() + offset));
}

// One byte at offset, 0 when out of range (mirrors le16/le32/le64). QByteArray::at is
// Q_ASSERT-only, so a raw .at on a size derived from on-disk data is an out-of-bounds
// read on a release build; route foreign-metadata byte reads through this instead.
uint8_t le8(const QByteArray& bytes, qsizetype offset) {
    if (offset < 0 || offset >= bytes.size()) {
        return 0;
    }
    return static_cast<uint8_t>(bytes.at(offset));
}

// A B-tree node's key count clamped to what its table-of-contents region can physically
// hold before the value area, so a corrupt btn_nkeys (up to 0xFFFFFFFF) cannot drive a
// per-entry parse loop ~4 billion iterations into a memory blow-up. A valid node's real
// nkeys is always <= this bound, so certified layouts are unaffected.
uint32_t boundedNodeKeyCount(const QByteArray& node,
                             qsizetype valueAreaEnd,
                             qsizetype tocEntryBytes) {
    const uint32_t nkeys = le32(node, kApfsBtreeNodeCountOffset);
    const qsizetype tocRoom = valueAreaEnd - kApfsBtreeNodeHeaderBytes;
    if (tocRoom <= 0 || tocEntryBytes <= 0) {
        return 0;
    }
    const auto capacity = static_cast<uint64_t>(tocRoom / tocEntryBytes);
    return static_cast<uint32_t>(std::min<uint64_t>(nkeys, capacity));
}

void writeAscii(QByteArray* bytes, qsizetype offset, const QByteArray& value, qsizetype maxBytes) {
    const qsizetype copyBytes = std::min(maxBytes, value.size());
    std::fill(bytes->begin() + offset, bytes->begin() + offset + maxBytes, '\0');
    std::copy(value.cbegin(), value.cbegin() + copyBytes, bytes->begin() + offset);
}

QByteArray newApfsObjectBlock(uint32_t blockSize,
                              uint64_t oid,
                              uint64_t xid,
                              uint32_t objectType,
                              uint32_t objectSubtype = 0) {
    QByteArray block(static_cast<qsizetype>(blockSize), '\0');
    writeLe64(&block, kApfsObjectOidOffset, oid);
    writeLe64(&block, kApfsObjectXidOffset, xid);
    writeLe32(&block, kApfsObjectTypeOffset, objectType);
    writeLe32(&block, kApfsObjectSubtypeOffset, objectSubtype);
    return block;
}

bool stampApfsObjectBlock(QByteArray* block, QStringList* blockers) {
    if (PartitionApfsWriter::stampObjectChecksum(block)) {
        return true;
    }
    if (blockers) {
        blockers->append(QStringLiteral("Unable to stamp APFS object checksum"));
    }
    return false;
}

// APFS container/volume UUIDs must be unique per instance (newfs_apfs emits a
// random v4 UUID). Returns the 16-byte RFC 4122 representation.
QByteArray randomApfsUuid() {
    return QUuid::createUuid().toRfc4122();
}

struct ApfsBtreeInfoFields {
    uint32_t blockSize{0};
    uint32_t flags{0};
    uint32_t keySize{0};
    uint32_t valueSize{0};
    uint64_t keyCount{0};
    uint64_t nodeCount{0};
};

void writeBtreeInfo(QByteArray* block, const ApfsBtreeInfoFields& fields) {
    const qsizetype info = static_cast<qsizetype>(fields.blockSize) - kApfsBtreeInfoBytes;
    writeLe32(block, info + kApfsBtreeInfoFlagsOffset, fields.flags);
    writeLe32(block, info + kApfsBtreeInfoNodeSizeOffset, fields.blockSize);
    writeLe32(block, info + kApfsBtreeInfoKeySizeOffset, fields.keySize);
    writeLe32(block, info + kApfsBtreeInfoValueSizeOffset, fields.valueSize);
    writeLe64(block, info + kApfsBtreeInfoKeyCountOffset, fields.keyCount);
    writeLe64(block, info + kApfsBtreeInfoNodeCountOffset, fields.nodeCount);
}

struct ApfsObjectMapEntry {
    uint64_t oid{0};
    uint64_t xid{0};
    uint64_t physicalBlock{0};
    // ov_flags (A6): OMAP_VAL_ENCRYPTED (0x4) marks the target virtual object
    // (the volume file-system tree) as AES-XTS-encrypted with the volume key.
    uint32_t flags{0};
};

// A physical omap FIXED_KV node's index_size (btn_table_space.len) is dictated by
// apfsck node_is_valid: LEAF omap value is a 16-byte apfs_omap_val so the min table
// is (blockSize-header)/(16+16+4)*4; an INDEX omap value is an 8-byte child paddr so
// it is (blockSize-header)/(16+8+4)*4. Both are hard-checked -- a leaf must carry the
// 448-byte TOC and an index the 576-byte TOC (at blockSize 4096) exactly.
qsizetype omapLeafTocBytes(uint32_t blockSize) {
    const qsizetype usable = static_cast<qsizetype>(blockSize) - kApfsBtreeNodeHeaderBytes;
    return usable /
           (kApfsObjectMapKeyBytes + kApfsObjectMapValueBytes + kApfsBtreeFixedTocEntryBytes) *
           kApfsBtreeFixedTocEntryBytes;
}

qsizetype omapIndexTocBytes(uint32_t blockSize) {
    const qsizetype usable = static_cast<qsizetype>(blockSize) - kApfsBtreeNodeHeaderBytes;
    return usable /
           (kApfsObjectMapKeyBytes + kApfsOmapIndexValueBytes + kApfsBtreeFixedTocEntryBytes) *
           kApfsBtreeFixedTocEntryBytes;
}

// Fanout of a single omap node. The 112-slot leaf / 144-slot index TOC is the
// structural size apfsck demands, but the number of records that actually FIT is bounded
// by BOTH the TOC-slot count AND the key+value data area (header + TOC + keys + values +
// (root ? btree_info trailer : 0) <= blockSize). A ROOT node reserves the 40-byte trailer,
// so a ROOT leaf holds one fewer record than a non-root leaf: 112 non-root vs 111 root at
// blockSize 4096. Getting this wrong overruns the value area into the trailer (the exact
// bug: 112 mappings took the single-node path and corrupted the last record).
qsizetype omapNodeCapacity(uint32_t blockSize,
                           qsizetype valueBytes,
                           qsizetype tocBytes,
                           bool isRoot) {
    const qsizetype tocSlots = tocBytes / kApfsBtreeFixedTocEntryBytes;
    const qsizetype dataArea = static_cast<qsizetype>(blockSize) - kApfsBtreeNodeHeaderBytes -
                               tocBytes - (isRoot ? kApfsBtreeInfoBytes : 0);
    const qsizetype dataSlots = dataArea / (kApfsObjectMapKeyBytes + valueBytes);
    return tocSlots < dataSlots ? tocSlots : dataSlots;
}

// Non-root leaf capacity (used for interior-level leaf packing).
qsizetype omapLeafCapacity(uint32_t blockSize) {
    return omapNodeCapacity(
        blockSize, kApfsObjectMapValueBytes, omapLeafTocBytes(blockSize), false);
}

// Single-node tree = a ROOT|LEAF node, so it reserves the trailer (one fewer than a
// non-root leaf). This is the threshold past which a multi-level tree is required.
qsizetype omapRootLeafCapacity(uint32_t blockSize) {
    return omapNodeCapacity(blockSize, kApfsObjectMapValueBytes, omapLeafTocBytes(blockSize), true);
}

// Non-root interior fanout.
qsizetype omapIndexCapacity(uint32_t blockSize) {
    return omapNodeCapacity(
        blockSize, kApfsOmapIndexValueBytes, omapIndexTocBytes(blockSize), false);
}

// A ROOT index node reserves the 40-byte btree_info trailer, so it holds fewer child
// pointers than an interior index node. Cap the topmost index level here so a full
// interior fanout never overflows the root.
qsizetype omapRootIndexCapacity(uint32_t blockSize) {
    return omapNodeCapacity(
        blockSize, kApfsOmapIndexValueBytes, omapIndexTocBytes(blockSize), true);
}

// Per-node fanout of a bulk-loaded physical B-tree: the non-root/root leaf capacity and
// the non-root/root interior capacity. Both the omap (fixed-KV) and the extent-ref tree
// (variable-KV) are physical trees with the same level structure, differing only in these
// capacities and the record serialization, so the shape math (physicalBtreeNodeTotal) and
// the emit order (omapEmitOrder) are shared.
struct ApfsPhysBtreeCaps {
    qsizetype leaf{0};
    qsizetype rootLeaf{0};
    qsizetype index{0};
    qsizetype rootIndex{0};
};

// Total node count a bulk-loaded physical B-tree over `count` records occupies (root +
// every interior + every leaf). A tree that fits a single ROOT|LEAF node holds the
// (smaller) root-leaf capacity; anything larger splits into at least two non-root leaves
// of the full leaf capacity, then index levels up to a root (the level that collapses to
// one node uses the smaller root capacity). Lets the reservation size the tree's block run
// before the nodes are built.
qsizetype physicalBtreeNodeTotal(qsizetype count, const ApfsPhysBtreeCaps& caps) {
    if (count <= caps.rootLeaf) {
        return 1;
    }
    qsizetype total = 0;
    qsizetype levelNodes = std::max<qsizetype>(2, (count + caps.leaf - 1) / caps.leaf);
    total += levelNodes;
    while (levelNodes > 1) {
        const qsizetype cap =
            levelNodes <= caps.index && levelNodes > caps.rootIndex ? caps.rootIndex : caps.index;
        levelNodes = (levelNodes + cap - 1) / cap;
        total += levelNodes;
    }
    return total;
}

// Mirrors buildObjectMapTreeNodes so the reservation can size the omap-tree block run.
qsizetype omapTreeBlockCount(qsizetype mappingCount, uint32_t blockSize) {
    return physicalBtreeNodeTotal(mappingCount,
                                  {omapLeafCapacity(blockSize),
                                   omapRootLeafCapacity(blockSize),
                                   omapIndexCapacity(blockSize),
                                   omapRootIndexCapacity(blockSize)});
}

// Extent-ref tree (a variable-KV physical B-tree) node fanout. A record is an 8-byte
// j_phys_ext_key, a value (20-byte j_phys_ext leaf value or an 8-byte index child paddr),
// and an 8-byte kvloc TOC entry; the TOC region rounds up to 64 bytes as the single-node
// writer lays it out, and a ROOT node reserves the 40-byte btree_info trailer. Returns the
// most records that fit -- the non-root leaf value 112, the root leaf 110 (the bound the
// former single-node guard fired at), the interior index 168, the root index 166.
constexpr qsizetype kApfsExtentRefKeyBytes = 8;
constexpr qsizetype kApfsExtentRefLeafValueBytes = 20;
constexpr qsizetype kApfsExtentRefIndexValueBytes = 8;

qsizetype extentRefTocBytes(qsizetype recordCount) {
    return std::max<qsizetype>(64,
                               ((recordCount * kApfsBtreeVariableTocEntryBytes + 63) / 64) * 64);
}

qsizetype extentRefNodeCapacity(uint32_t blockSize, qsizetype valueBytes, bool isRoot) {
    const qsizetype avail = static_cast<qsizetype>(blockSize) - kApfsBtreeNodeHeaderBytes -
                            (isRoot ? kApfsBtreeInfoBytes : 0);
    qsizetype fit = 0;
    for (qsizetype n = 1; extentRefTocBytes(n) + n * (kApfsExtentRefKeyBytes + valueBytes) <= avail;
         ++n) {
        fit = n;
    }
    return fit;
}

ApfsPhysBtreeCaps extentRefCaps(uint32_t blockSize) {
    return {extentRefNodeCapacity(blockSize, kApfsExtentRefLeafValueBytes, false),
            extentRefNodeCapacity(blockSize, kApfsExtentRefLeafValueBytes, true),
            extentRefNodeCapacity(blockSize, kApfsExtentRefIndexValueBytes, false),
            extentRefNodeCapacity(blockSize, kApfsExtentRefIndexValueBytes, true)};
}

// Node count a bulk-loaded extent-ref tree over `recordCount` j_phys_ext records occupies.
qsizetype extentRefTreeBlockCount(qsizetype recordCount, uint32_t blockSize) {
    return physicalBtreeNodeTotal(recordCount, extentRefCaps(blockSize));
}

// Block-layout offsets of the volume/container omap chain inside a commit's newBlocks
// vector, past the fs-tree nodes. The volume omap tree spans V blocks (it maps every
// fs-tree node, so it grows past a single node once the tree exceeds a leaf's capacity);
// the container omap tree spans C blocks (one, in practice -- a handful of volume
// mappings). tail is the first block past the whole chain (extent-ref / data area).
struct ApfsOmapChainLayout {
    qsizetype volOmapTreeBlocks{1};
    qsizetype ctrOmapTreeBlocks{1};
    uint64_t volOmapTreeBase{0};
    uint64_t volOmapHdr{0};
    uint64_t volSb{0};
    uint64_t ctrOmapTreeBase{0};
    uint64_t ctrOmapHdr{0};
    uint64_t tail{0};
    qsizetype chainBlocks{0};  // total blocks the chain occupies past the fs nodes
};

// V = omap-tree blocks for `volMappingCount` volume-omap mappings (one per fs-tree
// node); C = 1 for the container omap (a few volume mappings always fit one node).
ApfsOmapChainLayout omapChainLayout(uint64_t nodeCountBase,
                                    qsizetype volMappingCount,
                                    uint32_t blockSize) {
    ApfsOmapChainLayout layout;
    layout.volOmapTreeBlocks = omapTreeBlockCount(volMappingCount, blockSize);
    layout.ctrOmapTreeBlocks = 1;
    layout.volOmapTreeBase = nodeCountBase;
    layout.volOmapHdr = layout.volOmapTreeBase + static_cast<uint64_t>(layout.volOmapTreeBlocks);
    layout.volSb = layout.volOmapHdr + 1;
    layout.ctrOmapTreeBase = layout.volSb + 1;
    layout.ctrOmapHdr = layout.ctrOmapTreeBase + static_cast<uint64_t>(layout.ctrOmapTreeBlocks);
    layout.tail = layout.ctrOmapHdr + 1;
    layout.chainBlocks = static_cast<qsizetype>(layout.tail - nodeCountBase);
    return layout;
}

// One node of the bulk-loaded omap tree before paddrs are assigned: its records and
// (for interior nodes) the level it sits at. A leaf record's value is the 16-byte
// apfs_omap_val; an index record's value is the child node's index in the flat set.
struct ApfsOmapNodePlan {
    uint16_t level{0};
    QVector<ApfsObjectMapEntry> leafRecords;  // level 0 only
    QVector<qsizetype> childIndices;          // level > 0 only
    QVector<uint64_t> childKeyOid;            // level > 0: first oid of each child
    QVector<uint64_t> childKeyXid;            // level > 0: xid paired with that oid
    uint64_t firstOid{0};                     // this node's smallest key oid
    uint64_t firstXid{0};
};

void writeOmapLeafNode(QByteArray* block,
                       uint32_t blockSize,
                       const QVector<ApfsObjectMapEntry>& mappings,
                       bool isRoot) {
    const qsizetype tocBytes = omapLeafTocBytes(blockSize);
    const uint16_t rootFlag = isRoot ? kApfsBtreeNodeRoot : 0;
    writeLe16(block,
              kApfsBtreeNodeFlagsOffset,
              rootFlag | kApfsBtreeNodeLeaf | kApfsBtreeNodeFixedKvSize);
    writeLe16(block, kApfsBtreeNodeLevelOffset, 0);
    writeLe32(block, kApfsBtreeNodeCountOffset, static_cast<uint32_t>(mappings.size()));
    writeLe16(block, kApfsBtreeNodeTableOffsetOffset, 0);
    writeLe16(block, kApfsBtreeNodeTableLengthOffset, static_cast<uint16_t>(tocBytes));
    const qsizetype tableStart = kApfsBtreeNodeHeaderBytes;
    const qsizetype keyAreaStart = tableStart + tocBytes;
    const qsizetype valueAreaEnd = static_cast<qsizetype>(blockSize) -
                                   (isRoot ? kApfsBtreeInfoBytes : 0);
    const qsizetype keyBytesUsed = static_cast<qsizetype>(mappings.size()) * kApfsObjectMapKeyBytes;
    const qsizetype valueBytesUsed = static_cast<qsizetype>(mappings.size()) *
                                     kApfsObjectMapValueBytes;
    writeLe16(block, 0x2C, static_cast<uint16_t>(keyBytesUsed));
    writeLe16(block,
              0x2E,
              static_cast<uint16_t>(valueAreaEnd - keyAreaStart - keyBytesUsed - valueBytesUsed));
    writeLe16(block, 0x30, 0xFFFF);
    writeLe16(block, 0x32, 0);
    writeLe16(block, 0x34, 0xFFFF);
    writeLe16(block, 0x36, 0);
    for (qsizetype index = 0; index < mappings.size(); ++index) {
        const qsizetype toc = tableStart + index * kApfsBtreeFixedTocEntryBytes;
        const qsizetype keyOffset = index * kApfsObjectMapKeyBytes;
        const qsizetype valueBackOffset = (index + 1) * kApfsObjectMapValueBytes;
        const qsizetype key = keyAreaStart + keyOffset;
        const qsizetype value = valueAreaEnd - valueBackOffset;
        writeLe16(block, toc, static_cast<uint16_t>(keyOffset));
        writeLe16(block,
                  toc + kApfsBtreeFixedTocValueOffset,
                  static_cast<uint16_t>(valueBackOffset));
        writeLe64(block, key, mappings.at(index).oid);
        writeLe64(block, key + kApfsOmapKeyXidOffset, mappings.at(index).xid);
        writeLe32(block, value, mappings.at(index).flags);
        writeLe32(block, value + kApfsOmapValueSizeOffset, blockSize);
        writeLe64(block, value + kApfsOmapValuePaddrOffset, mappings.at(index).physicalBlock);
    }
}

// An interior (level > 0) omap node: 16-byte {oid, xid} keys, 8-byte child paddr
// values written backward from the value-area end (blockSize - info on the root).
void writeOmapIndexNode(QByteArray* block,
                        uint32_t blockSize,
                        const ApfsOmapNodePlan& plan,
                        const QVector<uint64_t>& childPaddrs,
                        bool isRoot) {
    const qsizetype tocBytes = omapIndexTocBytes(blockSize);
    const qsizetype count = plan.childIndices.size();
    const uint16_t rootFlag = isRoot ? kApfsBtreeNodeRoot : 0;
    writeLe16(block, kApfsBtreeNodeFlagsOffset, rootFlag | kApfsBtreeNodeFixedKvSize);
    writeLe16(block, kApfsBtreeNodeLevelOffset, plan.level);
    writeLe32(block, kApfsBtreeNodeCountOffset, static_cast<uint32_t>(count));
    writeLe16(block, kApfsBtreeNodeTableOffsetOffset, 0);
    writeLe16(block, kApfsBtreeNodeTableLengthOffset, static_cast<uint16_t>(tocBytes));
    const qsizetype tableStart = kApfsBtreeNodeHeaderBytes;
    const qsizetype keyAreaStart = tableStart + tocBytes;
    const qsizetype valueAreaEnd = static_cast<qsizetype>(blockSize) -
                                   (isRoot ? kApfsBtreeInfoBytes : 0);
    const qsizetype keyBytesUsed = count * kApfsObjectMapKeyBytes;
    const qsizetype valueBytesUsed = count * kApfsOmapIndexValueBytes;
    writeLe16(block, 0x2C, static_cast<uint16_t>(keyBytesUsed));
    writeLe16(block,
              0x2E,
              static_cast<uint16_t>(valueAreaEnd - keyAreaStart - keyBytesUsed - valueBytesUsed));
    writeLe16(block, 0x30, 0xFFFF);
    writeLe16(block, 0x32, 0);
    writeLe16(block, 0x34, 0xFFFF);
    writeLe16(block, 0x36, 0);
    for (qsizetype index = 0; index < count; ++index) {
        const qsizetype toc = tableStart + index * kApfsBtreeFixedTocEntryBytes;
        const qsizetype keyOffset = index * kApfsObjectMapKeyBytes;
        const qsizetype valueBackOffset = (index + 1) * kApfsOmapIndexValueBytes;
        const qsizetype key = keyAreaStart + keyOffset;
        const qsizetype value = valueAreaEnd - valueBackOffset;
        writeLe16(block, toc, static_cast<uint16_t>(keyOffset));
        writeLe16(block,
                  toc + kApfsBtreeFixedTocValueOffset,
                  static_cast<uint16_t>(valueBackOffset));
        writeLe64(block, key, plan.childKeyOid.at(index));
        writeLe64(block, key + kApfsOmapKeyXidOffset, plan.childKeyXid.at(index));
        writeLe64(block, value, childPaddrs.at(plan.childIndices.at(index)));
    }
}

// Pack the sorted mappings into level-0 leaf plans, appending them to `plans`. A tree
// that fits one ROOT|LEAF node (<= root-leaf capacity, which reserves the trailer) stays
// a single node; otherwise it splits into >= 2 non-root leaves -- a lone non-root leaf
// cannot exist (it would BE the root at the smaller capacity), so counts in
// (rootLeafCap, leafCap] still yield two leaves.
qsizetype planOmapLeaves(const QVector<ApfsObjectMapEntry>& sorted,
                         uint32_t blockSize,
                         QVector<ApfsOmapNodePlan>* plans) {
    const qsizetype leafCap = omapLeafCapacity(blockSize);
    qsizetype leafNodes = 1;
    if (sorted.size() > omapRootLeafCapacity(blockSize)) {
        leafNodes = std::max<qsizetype>(2, (sorted.size() + leafCap - 1) / leafCap);
    }
    const qsizetype perLeaf = (sorted.size() + leafNodes - 1) / std::max<qsizetype>(1, leafNodes);
    for (qsizetype node = 0; node < leafNodes; ++node) {
        ApfsOmapNodePlan plan;
        plan.level = 0;
        const qsizetype start = node * perLeaf;
        for (qsizetype j = start; j < std::min(start + perLeaf, sorted.size()); ++j) {
            plan.leafRecords.append(sorted.at(j));
        }
        if (!plan.leafRecords.isEmpty()) {
            plan.firstOid = plan.leafRecords.first().oid;
            plan.firstXid = plan.leafRecords.first().xid;
        }
        plans->append(plan);
    }
    return leafNodes;
}

// One index level: pack `childTotal` children (starting at flat index `childBase`) into
// index-node plans at `level`, appending them to `plans`. Returns the node count made.
qsizetype planOmapIndexLevel(uint32_t blockSize,
                             uint16_t level,
                             qsizetype childBase,
                             qsizetype childTotal,
                             QVector<ApfsOmapNodePlan>* plans) {
    const qsizetype indexCap = omapIndexCapacity(blockSize);
    const qsizetype rootCap = omapRootIndexCapacity(blockSize);
    // The level that collapses to one node is the root and must respect the smaller root
    // capacity; an intermediate level uses the full interior fanout.
    const qsizetype cap = childTotal <= indexCap && childTotal > rootCap ? rootCap : indexCap;
    qsizetype made = 0;
    for (qsizetype start = 0; start < childTotal; start += cap) {
        ApfsOmapNodePlan plan;
        plan.level = level;
        for (qsizetype j = start; j < std::min(start + cap, childTotal); ++j) {
            const qsizetype childIndex = childBase + j;
            plan.childIndices.append(childIndex);
            plan.childKeyOid.append(plans->at(childIndex).firstOid);
            plan.childKeyXid.append(plans->at(childIndex).firstXid);
        }
        plan.firstOid = plan.childKeyOid.first();
        plan.firstXid = plan.childKeyXid.first();
        plans->append(plan);
        ++made;
    }
    return made;
}

// Emit-order = root first (node[0]), then every other plan in build order. Returns the
// emit order and fills paddrOfPlan with each plan's assigned block. Slot i takes
// nodeBlocks[i] -- the ACTUAL reserved block, which is NOT treeBasePaddr+i once free space
// is fragmented (the reserved omap-tree run can be non-contiguous). Passing a consecutive
// run keeps a single-node tree and a fresh-image tree byte-identical to treeBasePaddr+slot.
QVector<qsizetype> omapEmitOrder(qsizetype planCount,
                                 qsizetype rootIndex,
                                 const QVector<uint64_t>& nodeBlocks,
                                 QVector<uint64_t>* paddrOfPlan) {
    QVector<qsizetype> order;
    order.append(rootIndex);
    for (qsizetype i = 0; i < planCount; ++i) {
        if (i != rootIndex) {
            order.append(i);
        }
    }
    for (qsizetype slot = 0; slot < order.size(); ++slot) {
        (*paddrOfPlan)[order.at(slot)] = nodeBlocks.at(slot);
    }
    return order;
}

void writeOmapRootTrailer(QByteArray* block,
                          uint32_t blockSize,
                          uint64_t mappingCount,
                          uint64_t totalNodes) {
    const qsizetype infoOffset = static_cast<qsizetype>(blockSize) - kApfsBtreeInfoBytes;
    writeLe32(block, infoOffset + kApfsBtreeInfoFlagsOffset, 0x00'00'00'12);
    writeLe32(block, infoOffset + kApfsBtreeInfoNodeSizeOffset, blockSize);
    writeLe32(block, infoOffset + kApfsBtreeInfoKeySizeOffset, kApfsObjectMapKeyBytes);
    writeLe32(block, infoOffset + kApfsBtreeInfoValueSizeOffset, kApfsObjectMapValueBytes);
    if (mappingCount != 0) {
        writeLe32(block, infoOffset + 16, kApfsObjectMapKeyBytes);
        writeLe32(block, infoOffset + 20, kApfsObjectMapValueBytes);
    }
    writeLe64(block, infoOffset + kApfsBtreeInfoKeyCountOffset, mappingCount);
    writeLe64(block, infoOffset + kApfsBtreeInfoNodeCountOffset, totalNodes);
}

struct ApfsOmapEmitContext {
    uint32_t blockSize{0};
    uint64_t rootOid{0};
    uint64_t xid{0};
    uint64_t mappingCount{0};
    uint64_t totalNodes{0};
    qsizetype rootIndex{0};
    const QVector<uint64_t>* paddrOfPlan{nullptr};
};

// Serialize one omap node plan (identified by its flat index) to a stamped block. apfsck
// checks the object TYPE: a physical B-tree root is BTREE (PHYSICAL|0x02), a non-root node
// BTREE_NODE (PHYSICAL|0x03) -- "wrong object type for nonroot" otherwise. Every physical
// omap node's stored OID equals its own paddr; only the root keeps the caller's rootOid.
QByteArray emitOmapNode(const ApfsOmapNodePlan& plan,
                        qsizetype planIndex,
                        const ApfsOmapEmitContext& ctx,
                        QStringList* blockers) {
    const bool isRoot = planIndex == ctx.rootIndex;
    const uint64_t nodePaddr = ctx.paddrOfPlan->at(planIndex);
    const uint32_t objectType = isRoot ? kApfsObjectTypeBtreePhysical
                                       : (kApfsObjStoragePhysical | kApfsObjectTypeBtreeNode);
    QByteArray block =
        newApfsObjectBlock(ctx.blockSize, isRoot ? ctx.rootOid : nodePaddr, ctx.xid, objectType);
    writeLe32(&block, kApfsObjectSubtypeOffset, 0x00'00'00'0B);
    if (plan.level == 0) {
        writeOmapLeafNode(&block, ctx.blockSize, plan.leafRecords, isRoot);
    } else {
        writeOmapIndexNode(&block, ctx.blockSize, plan, *ctx.paddrOfPlan, isRoot);
    }
    if (isRoot) {
        writeOmapRootTrailer(&block, ctx.blockSize, ctx.mappingCount, ctx.totalNodes);
    }
    stampApfsObjectBlock(&block, blockers);
    return block;
}

// The addressing a bulk-loaded physical omap needs: the root node's stored OID plus the
// paddr of every emitted node (emit slot i is written to nodeBlocks[i]). rootOid usually
// equals nodeBlocks[0] (apfsck resolves the root via the header's om_tree_oid = the root
// paddr). When nodeBlocks is empty the nodes take treeBasePaddr+i (a consecutive run), for
// the single-node / fresh-image callers whose reserved run IS contiguous. The COW commit
// must pass the ACTUAL reserved run because fragmented free space makes it non-contiguous;
// a consecutive assumption there wrote the second omap leaf onto a data block and pointed
// the root at it, so the next read decoded that data block as a node (checksum failure).
struct ApfsOmapTreeParams {
    uint32_t blockSize{0};
    uint64_t rootOid{0};
    uint64_t xid{0};
    uint64_t treeBasePaddr{0};
    QVector<uint64_t> nodeBlocks;  // empty = consecutive from treeBasePaddr
};

// The paddr each emit slot is written to: the caller's explicit reserved run, or a
// consecutive run from treeBasePaddr when none was given. `count` nodes are needed.
QVector<uint64_t> omapNodeBlocks(const ApfsOmapTreeParams& params, qsizetype count) {
    if (!params.nodeBlocks.isEmpty()) {
        return params.nodeBlocks;
    }
    QVector<uint64_t> consecutive;
    consecutive.reserve(count);
    for (qsizetype i = 0; i < count; ++i) {
        consecutive.append(params.treeBasePaddr + static_cast<uint64_t>(i));
    }
    return consecutive;
}

// Bulk-load a physical omap B-tree (subtype 0x0B) over `mappings`, returning every node
// block; node[0] is the root at nodeBlocks[0], node[i] at nodeBlocks[i]. One node (<=
// root-leaf capacity) is byte-identical to the single ROOT|LEAF layout newfs_apfs emits;
// more mappings split into leaves under index nodes up to a root.
QVector<QByteArray> buildObjectMapTreeNodes(const ApfsOmapTreeParams& params,
                                            const QVector<ApfsObjectMapEntry>& mappings,
                                            QStringList* blockers) {
    QVector<ApfsObjectMapEntry> sorted = mappings;
    std::sort(sorted.begin(),
              sorted.end(),
              [](const ApfsObjectMapEntry& a, const ApfsObjectMapEntry& b) {
                  return a.oid != b.oid ? a.oid < b.oid : a.xid < b.xid;
              });
    QVector<ApfsOmapNodePlan> plans;
    QVector<qsizetype> levelStart{0};
    QVector<qsizetype> levelCount{planOmapLeaves(sorted, params.blockSize, &plans)};
    uint16_t level = 1;
    while (levelCount.last() > 1) {
        const qsizetype childBase = levelStart.last();
        levelStart.append(plans.size());
        levelCount.append(
            planOmapIndexLevel(params.blockSize, level, childBase, levelCount.last(), &plans));
        ++level;
    }
    const qsizetype rootIndex = plans.size() - 1;
    const QVector<uint64_t> nodeBlocks = omapNodeBlocks(params, plans.size());
    if (nodeBlocks.size() < plans.size()) {
        blockers->append(
            QStringLiteral("APFS object map tree needs %1 node blocks but only %2 were provided")
                .arg(plans.size())
                .arg(nodeBlocks.size()));
        return {};
    }
    QVector<uint64_t> paddrOfPlan(plans.size(), 0);
    const QVector<qsizetype> emitOrder =
        omapEmitOrder(plans.size(), rootIndex, nodeBlocks, &paddrOfPlan);
    const ApfsOmapEmitContext ctx{params.blockSize,
                                  params.rootOid,
                                  params.xid,
                                  static_cast<uint64_t>(sorted.size()),
                                  static_cast<uint64_t>(plans.size()),
                                  rootIndex,
                                  &paddrOfPlan};
    QVector<QByteArray> blocks;
    blocks.reserve(plans.size());
    for (const qsizetype planIndex : emitOrder) {
        blocks.append(emitOmapNode(plans.at(planIndex), planIndex, ctx, blockers));
    }
    return blocks;
}

QByteArray buildObjectMapTreeBlock(uint32_t blockSize,
                                   uint64_t oid,
                                   const QVector<ApfsObjectMapEntry>& mappings,
                                   uint64_t xid,
                                   QStringList* blockers) {
    // Single-node object-map root/leaf mirrored from newfs_apfs output: fixed
    // 448-byte TOC, info flags FIXED_KV|SEQUENTIAL_INSERT (0x12), 16-byte keys and
    // values. Callers whose mapping count can exceed one node must instead reserve
    // omapTreeBlockCount() blocks and emit buildObjectMapTreeNodes(); this single-block
    // helper stays for the container omap (a handful of volume mappings) and asserts it
    // never silently overflows the leaf TOC.
    if (mappings.size() > omapRootLeafCapacity(blockSize)) {
        blockers->append(
            QStringLiteral("APFS object map has %1 mappings, exceeding a single ROOT|LEAF node's "
                           "capacity of %2; a multi-level omap tree is required")
                .arg(mappings.size())
                .arg(omapRootLeafCapacity(blockSize)));
        return newApfsObjectBlock(blockSize, oid, xid, kApfsObjectTypeBtreePhysical);
    }
    const QVector<QByteArray> nodes =
        buildObjectMapTreeNodes({blockSize, oid, xid, oid}, mappings, blockers);
    return nodes.isEmpty() ? QByteArray() : nodes.first();
}

struct ApfsBtreeKeyValue {
    QByteArray key;
    QByteArray value;
};

// One contiguous run of a file's data: the file-logical block where the run
// starts, its physical start block, and its block count. A file whose data is
// fragmented across free space carries several of these.
struct ApfsDataExtent {
    uint64_t logicalBlock{0};
    uint64_t paddr{0};
    uint64_t blockCount{0};
};

// A large extended attribute stored as a DATA STREAM (macOS uses this above the ~3804-byte embedded
// limit): a j_xattr_dstream naming a fresh object id whose file-extent records hold the value's
// blocks. Recovered from a real Apple file so an in-place mutation preserves it byte-for-byte.
struct ApfsDataStreamXattr {
    QByteArray name;
    uint64_t objId{0};
    uint64_t size{0};         // the attribute value's byte length (dstream size)
    uint64_t allocedSize{0};  // block-aligned allocated bytes (dstream alloced_size)
    QVector<ApfsDataExtent> extents;
};

// A7 (A-h) hard link: one additional name (beyond a file's primary name) resolving to
// the same inode. parentId is the directory holding the name; siblingId is the unique
// sibling-record id assigned to it.
struct ApfsHardLinkName {
    QString name;
    uint64_t parentId{kApfsRootDirectoryId};
    uint64_t siblingId{0};
};

struct ApfsRootFilePayload {
    QString fileName;
    QString parentDirectoryName;
    QByteArray data;
    uint64_t parentDirectoryId{kApfsRootDirectoryId};
    uint64_t fileId{0};
    uint64_t privateId{0};
    uint64_t dataStartBlock{0};
    // Empty: the data is the single contiguous run at dataStartBlock (the original
    // path, byte-identical). Non-empty: an explicit multi-run extent list.
    QVector<ApfsDataExtent> dataExtents;
    // Transparent compression (A5): when set, the file carries no data stream;
    // its logical content lives in an embedded com.apple.decmpfs xattr
    // (decmpfsXattr) and its inode is UF_COMPRESSED with uncompressedSize bytes.
    // `data` is empty for a compressed file (no extents are allocated).
    bool compressed{false};
    QByteArray decmpfsXattr;
    uint64_t uncompressedSize{0};
    // A5 follow-on resource-fork compression: when set, this compressed file keeps its
    // (still compressed) content in a com.apple.ResourceFork data stream rather than the
    // inline decmpfs xattr, because the compressed bytes exceed the 3804-byte embedded
    // limit. `data` holds the resource-fork "cmpf" blob (allocated + written like normal
    // file data, but its extents are owned by resourceForkXattrObjId, a fresh object id),
    // decmpfsXattr is the bare 16-byte header (algo *_RSRC), and uncompressedSize is the
    // original logical size. The inode is UF_COMPRESSED with no data-stream xfield.
    bool resourceFork{false};
    uint64_t resourceForkXattrObjId{0};
    // A7 (A-h): arbitrary named extended attributes (user xattrs, ACL blobs in
    // com.apple.system.Security, Finder info, ...). Each becomes a j_xattr record
    // with an embedded value. Empty keeps the certified layout byte-identical.
    QVector<QPair<QByteArray, QByteArray>> xattrs;
    // A large (> ~3804 byte) extended attribute macOS stores as a DATA-STREAM xattr: its value
    // lives in a stream owned by a fresh object id (not the inode). Preserved in place across a
    // mutation (its extents are kept, its j_xattr_dstream + file-extent records re-emitted). Empty
    // keeps every file byte-identical. Only populated by recoverInodeState for a real Apple file.
    QVector<ApfsDataStreamXattr> streamXattrs;
    // A7 (A-h): when set, the inode is sparse -- the dstream logical size exceeds
    // the bytes its extents cover, and the uncovered logical ranges read as zeros
    // (a hole). The reader already zero-fills gaps between extents.
    bool sparse{false};
    uint64_t sparseLogicalSize{0};
    // A7 (A-h): extra internal_flags OR-ed into the inode (WAS_CLONED / WAS_EVER_CLONED
    // on a clone). 0 keeps every other file byte-identical.
    uint64_t extraInodeFlags{0};
    // A7 (A-h) hard links: additional names (beyond fileName) that resolve to THIS
    // inode. When non-empty the file is hard-linked: nlink == 1 + additionalLinks
    // count, every name (primary + additional) carries a sibling-id dentry xfield and
    // gets a sibling-link + sibling-map record, and primarySiblingId is the lowest of
    // the sibling ids (Apple stores the primary name as the lowest-id sibling). Empty
    // keeps a single-link file byte-identical.
    QVector<ApfsHardLinkName> additionalLinks;
    uint64_t primarySiblingId{0};
    // Streaming write: the file's logical size when `data` carries no bytes (the
    // payload is streamed block-by-block from a host file, not held in RAM). 0 =
    // use data.size() (every in-memory path stays byte-identical). The data extents
    // still come from dataExtents; this only feeds the inode logical size + the
    // synthesized single-extent block count.
    uint64_t logicalSizeOverride{0};
    // A6 per-file-key encryption (APFS data-protection model): when cryptoId != 0
    // this file's data extents are AES-XTS encrypted with perFileKey (32 raw bytes;
    // the on-disk 40-byte RFC3394(VEK, perFileKey) ciphertext is wrappedFileKey), the
    // XTS tweak base of file-logical block b being (cryptoId + b) (apfs-fuse:
    // extent_crypto_id + blk_idx). The fs-tree carries a j_crypto_state record at
    // cryptoId (refcnt = the inode dstream ref + the file's extent count), the inode
    // reports default_protection_class = protectionClass, and the dstream + every
    // file-extent record carry default_crypto_id = crypto_id = cryptoId. 0 keeps every
    // plaintext file byte-identical.
    uint64_t cryptoId{0};
    QByteArray perFileKey;      // 32 raw bytes; encrypts the data blocks (never on disk)
    QByteArray wrappedFileKey;  // 40 bytes = RFC3394(VEK, perFileKey); the on-disk key
    uint32_t protectionClass{0};
    // Preservation: the original inode's resource-fork internal_flags bits (NO_RSRC_FORK /
    // HAS_RSRC_FORK) are carried VERBATIM in extraInodeFlags -- including the kernel-written
    // "neither bit" form on a dstream-decmpfs file -- instead of re-deriving NO_RSRC_FORK.
    // False keeps every generated file byte-identical.
    bool preservedRsrcBits{false};
    // Preservation of a NON-REGULAR inode (symlink / FIFO / socket / device): its full
    // st_mode (type + permission bits). The inode emits with this mode, its dirent with the
    // matching DT_* type, and NO data stream (a symlink's target rides in its embedded
    // com.apple.fs.symlink xattr). 0 = regular file (byte-identical everywhere else).
    uint16_t specialMode{0};
    // A device inode's rdev, re-emitted as an INO_EXT_TYPE_RDEV xfield (0 = none).
    uint32_t rdev{0};
    // Preserved embedded xattrs carried VERBATIM with their j_xattr_val flags (e.g. the
    // FILE_SYSTEM_OWNED bit on com.apple.fs.symlink -- apfsck rejects a symlink target
    // xattr without it). `xattrs` (above) stays the generated-attribute path with plain
    // DATA_EMBEDDED flags.
    QVector<ApfsRecoveredXattr> preservedXattrs;
};

// Group ascending block addresses into contiguous runs, assigning each run its
// file-logical start block (the cumulative block index).
QVector<ApfsDataExtent> groupContiguousRuns(const QVector<uint64_t>& blocks) {
    QVector<ApfsDataExtent> extents;
    uint64_t logical = 0;
    for (uint64_t block : blocks) {
        if (!extents.isEmpty() && extents.last().paddr + extents.last().blockCount == block) {
            extents.last().blockCount += 1;
        } else {
            extents.append({logical, block, 1});
        }
        logical += 1;
    }
    return extents;
}

struct ApfsRootDirectoryPayload {
    QString directoryName;
    uint64_t directoryId{0};
    uint64_t privateId{0};
    // Object id of the directory that contains this one. Root children carry
    // kApfsRootDirectoryId (the default), so a flat or single-level tree is
    // byte-identical to the certified layout; nested directories carry their real
    // parent's object id.
    uint64_t parentDirectoryId{kApfsRootDirectoryId};
};

uint32_t crc32cWord(uint32_t crc, uint32_t word) {
    for (int byteIndex = 0; byteIndex < 4; ++byteIndex) {
        crc ^= (word >> (byteIndex * 8)) & 0xFF;
        for (int bit = 0; bit < 8; ++bit) {
            crc = (crc >> 1) ^ ((crc & 1) ? 0x82'F6'3B'78u : 0u);
        }
    }
    return crc;
}

