PartitionApfsWritePreflight PartitionApfsWriter::validateImageOnlyExecutionEvidence(
    const PartitionApfsImageMutationPlan& plan,
    const PartitionApfsWriterExecutionEvidence& evidence) {
    PartitionApfsWritePreflight result;
    result.required_evidence = enterpriseCertificationRequirements();
    appendPlanEvidenceMismatchBlockers(plan, evidence, &result);
    appendMissingExecutionEvidenceBlockers(plan, evidence, &result);
    if (!evidence.hardware_raw_media_verified) {
        result.warnings.append(
            QStringLiteral("APFS image-only evidence is not raw-media certification; raw helper "
                           "execution still requires separate hardware evidence"));
    }
    result.allowed = result.blockers.isEmpty();
    return result;
}

QVector<QByteArray> PartitionApfsWriter::buildFsTreeNodeBlocks(uint32_t block_size,
                                                               const QStringList& file_names,
                                                               uint64_t first_leaf_oid,
                                                               QStringList* blockers) {
    QStringList localBlockers;
    QStringList* sink = blockers != nullptr ? blockers : &localBlockers;
    QVector<ApfsRootFilePayload> files;
    files.reserve(file_names.size());
    for (qsizetype index = 0; index < file_names.size(); ++index) {
        files.append({.fileName = file_names.at(index),
                      .parentDirectoryId = kApfsRootDirectoryId,
                      .fileId = kApfsFirstUserObjectId + static_cast<uint64_t>(index),
                      .privateId = kApfsFirstUserObjectId + static_cast<uint64_t>(index)});
    }
    QVector<ApfsFsTreeNode> nodes;
    if (!buildFsTreeNodes({block_size, files, {}, first_leaf_oid}, &nodes, sink)) {
        return {};
    }
    QVector<QByteArray> blocks;
    blocks.reserve(nodes.size());
    for (const auto& node : nodes) {
        blocks.append(node.block);
    }
    return blocks;
}

QVector<QByteArray> PartitionApfsWriter::buildObjectMapTreeBlocks(uint32_t block_size,
                                                                  uint64_t tree_base_paddr,
                                                                  uint64_t xid,
                                                                  qsizetype mapping_count,
                                                                  QStringList* blockers) {
    QStringList localBlockers;
    QStringList* sink = blockers != nullptr ? blockers : &localBlockers;
    QVector<ApfsObjectMapEntry> mappings;
    mappings.reserve(mapping_count);
    // Synthetic mappings with distinct, ascending oids so the leaf/index key ordering
    // and the paddr value writes are exercised end to end.
    for (qsizetype index = 0; index < mapping_count; ++index) {
        const uint64_t oid = kApfsFirstUserObjectId + static_cast<uint64_t>(index);
        mappings.append({oid, xid, tree_base_paddr + static_cast<uint64_t>(index) + 1, 0});
    }
    return buildObjectMapTreeNodes({block_size, tree_base_paddr, xid, tree_base_paddr},
                                   mappings,
                                   sink);
}

QVector<QByteArray> PartitionApfsWriter::buildMainFreeQueueTreeBlocks(uint32_t block_size,
                                                                      uint64_t leaf_base_oid,
                                                                      uint64_t xid,
                                                                      qsizetype entry_count,
                                                                      QStringList* blockers) {
    QStringList localBlockers;
    QStringList* sink = blockers != nullptr ? blockers : &localBlockers;
    // Synthetic single-block runs at distinct, ascending paddrs (all length 1 -> ghosts) so
    // the {xid, paddr} key ordering and the leaf/index packing are exercised end to end. A
    // non-consecutive stride keeps them from coalescing into one run.
    QVector<ApfsFreeQueueEntry> entries;
    entries.reserve(entry_count);
    for (qsizetype index = 0; index < entry_count; ++index) {
        entries.append({xid, 1000 + static_cast<uint64_t>(index) * 2, 1});
    }
    return buildMainFreeQueueNodes({block_size, kApfsFormatFqMainTreeOid, leaf_base_oid, xid},
                                   entries,
                                   sink)
        .blocks;
}

QVector<QPair<quint64, quint64>> PartitionApfsWriter::readMainFreeQueueTreeBlocks(
    const QVector<QByteArray>& node_blocks, uint32_t block_size) {
    QVector<QPair<quint64, quint64>> out;
    if (node_blocks.isEmpty()) {
        return out;
    }
    // Decode one free-queue leaf block into {xid, paddr} pairs, mirroring parseFreeQueueEntries
    // (root-flag-aware value area) but without needing an on-disk device.
    const auto decodeLeaf = [block_size, &out](const QByteArray& node) {
        const uint32_t nkeys = le32(node, kApfsBtreeNodeCountOffset);
        const qsizetype keyStart = kApfsBtreeNodeHeaderBytes +
                                   le16(node, kApfsBtreeNodeTableLengthOffset);
        for (uint32_t index = 0; index < nkeys; ++index) {
            const uint16_t koff = le16(node, kApfsBtreeNodeHeaderBytes + index * 4);
            out.append({le64(node, keyStart + koff), le64(node, keyStart + koff + 8)});
        }
    };
    const QByteArray& root = node_blocks.first();
    if (le16(root, kApfsBtreeNodeLevelOffset) == 0) {
        decodeLeaf(root);  // single root-leaf tree
        return out;
    }
    // Multi-node: the leaves follow the root in build order (blocks[1..]); the root's index
    // records key them but the diagnostic walks the vector directly (no checkpoint map).
    for (qsizetype i = 1; i < node_blocks.size(); ++i) {
        decodeLeaf(node_blocks.at(i));
    }
    return out;
}

QVector<QByteArray> PartitionApfsWriter::buildExtentRefTreeBlocksForTesting(
    uint32_t block_size,
    uint64_t tree_base_paddr,
    uint64_t xid,
    qsizetype record_count,
    QStringList* blockers) {
    QStringList localBlockers;
    QStringList* sink = blockers != nullptr ? blockers : &localBlockers;
    // Synthetic files: each a distinct one-block extent at an ascending, non-coalescing paddr
    // well clear of the tree's own node run, owned by id 1000+i.
    QVector<ApfsRootFilePayload> files;
    files.reserve(record_count);
    for (qsizetype index = 0; index < record_count; ++index) {
        ApfsRootFilePayload file;
        file.fileId = 1000 + static_cast<uint64_t>(index);
        file.dataExtents = {{0, tree_base_paddr + 100'000 + static_cast<uint64_t>(index) * 2, 1}};
        files.append(file);
    }
    const qsizetype nodeTotal = extentRefTreeBlockCount(record_count, block_size);
    QVector<uint64_t> run;
    run.reserve(nodeTotal);
    for (qsizetype i = 0; i < nodeTotal; ++i) {
        run.append(tree_base_paddr + static_cast<uint64_t>(i));
    }
    return buildExtentRefTreeNodes({block_size, xid, run}, files, sink);
}

QVector<QPair<quint64, quint64>> PartitionApfsWriter::readExtentRefTreeBlocksForTesting(
    const QVector<QByteArray>& node_blocks, uint32_t block_size) {
    // Flatten every LEAF node's {owner id, data paddr} records (index nodes carry no records).
    // A correct multi-node build packs all records into its leaves, so this returns the whole
    // set regardless of tree depth, without needing an on-disk device.
    QVector<QPair<quint64, quint64>> out;
    for (const QByteArray& node : node_blocks) {
        if (le16(node, kApfsBtreeNodeLevelOffset) != 0) {
            continue;
        }
        QHash<uint64_t, uint64_t> owners;
        const ApfsExtentRefWalk leaf{nullptr, {block_size, 0}, &owners, nullptr, 0};
        collectExtentRefLeafOwners(node, leaf);
        for (auto it = owners.constBegin(); it != owners.constEnd(); ++it) {
            out.append({it.key(), it.value()});
        }
    }
    return out;
}

QPair<quint64, quint64> PartitionApfsWriter::nextCrashSafeIpSlot(quint64 live_cib,
                                                                 quint64 block_count) {
    const ApfsIpSlot slot = nextIpSlot(live_cib, computeGeneratedLayout(block_count));
    return {slot.cib, slot.bitmap};
}

quint64 PartitionApfsWriter::readGeneratedLiveCibAddr(const QString& image_path) {
    QFile image(image_path);
    if (!image.open(QIODevice::ReadOnly)) {
        return 0;
    }
    uint32_t blockSize = 0;
    uint64_t blockCount = 0;
    QStringList blockers;
    if (!readApfsRepairGeometry(&image, &blockSize, &blockCount, &blockers)) {
        return 0;
    }
    const ApfsRepairGeometry geometry{blockSize, blockCount};
    QByteArray nxsb(blockSize, '\0');
    if (!readApfsRepairBlock(&image, geometry, kApfsFormatNxsbBlock, &nxsb, &blockers)) {
        return 0;
    }
    return readLiveSpacemanCibAddr(&image, geometry, nxsb, &blockers);
}

quint64 PartitionApfsWriter::readGeneratedChunkBitmapAddr(const QString& image_path,
                                                          quint64 chunk_index) {
    QFile image(image_path);
    if (!image.open(QIODevice::ReadOnly)) {
        return 0;
    }
    uint32_t blockSize = 0;
    uint64_t blockCount = 0;
    QStringList blockers;
    if (!readApfsRepairGeometry(&image, &blockSize, &blockCount, &blockers)) {
        return 0;
    }
    const ApfsRepairGeometry geometry{blockSize, blockCount};
    QByteArray nxsb(blockSize, '\0');
    if (!readApfsRepairBlock(&image, geometry, kApfsFormatNxsbBlock, &nxsb, &blockers)) {
        return 0;
    }
    // S4b: resolve the chunk-info block that OWNS this chunk (cib chunk_index/126) from the
    // live cib-array, then index the entry local to it (chunk_index % 126). A chunk cib k>0
    // owns is read from cib k's current address, not the live cib 0.
    const uint64_t ownerCibIndex = chunk_index / kApfsSpacemanChunksPerCib;
    const QVector<uint64_t> addrs =
        readLiveSpacemanCibArray(&image, geometry, nxsb, ownerCibIndex + 1, &blockers);
    const uint64_t ownerAddr = addrs.value(static_cast<qsizetype>(ownerCibIndex), 0);
    QByteArray cib(blockSize, '\0');
    if (ownerAddr == 0 || !readApfsRepairBlock(&image, geometry, ownerAddr, &cib, &blockers)) {
        return 0;
    }
    const qsizetype entry = kApfsChunkInfoEntriesOffset +
                            static_cast<qsizetype>(chunk_index % kApfsSpacemanChunksPerCib) *
                                kApfsChunkInfoEntryStride;
    return le64(cib, entry + kApfsChunkInfoEntryBitmapAddrOffset);
}

quint64 PartitionApfsWriter::readGeneratedChunkFreeCount(const QString& image_path,
                                                         quint64 chunk_index) {
    QFile image(image_path);
    if (!image.open(QIODevice::ReadOnly)) {
        return 0;
    }
    uint32_t blockSize = 0;
    uint64_t blockCount = 0;
    QStringList blockers;
    if (!readApfsRepairGeometry(&image, &blockSize, &blockCount, &blockers)) {
        return 0;
    }
    const ApfsRepairGeometry geometry{blockSize, blockCount};
    QByteArray nxsb(blockSize, '\0');
    if (!readApfsRepairBlock(&image, geometry, kApfsFormatNxsbBlock, &nxsb, &blockers)) {
        return 0;
    }
    // Resolve the chunk-info block that OWNS this chunk (cib chunk_index/126) from the live
    // cib-array, then index the entry local to it (chunk_index % 126), same as the bitmap-addr
    // reader; return its ci_free_count.
    const uint64_t ownerCibIndex = chunk_index / kApfsSpacemanChunksPerCib;
    const QVector<uint64_t> addrs =
        readLiveSpacemanCibArray(&image, geometry, nxsb, ownerCibIndex + 1, &blockers);
    const uint64_t ownerAddr = addrs.value(static_cast<qsizetype>(ownerCibIndex), 0);
    QByteArray cib(blockSize, '\0');
    if (ownerAddr == 0 || !readApfsRepairBlock(&image, geometry, ownerAddr, &cib, &blockers)) {
        return 0;
    }
    const qsizetype entry = kApfsChunkInfoEntriesOffset +
                            static_cast<qsizetype>(chunk_index % kApfsSpacemanChunksPerCib) *
                                kApfsChunkInfoEntryStride;
    return le32(cib, entry + kApfsChunkInfoEntryFreeCountOffset);
}

int PartitionApfsWriter::readGeneratedVolumeOmapTreeLevel(const QString& image_path) {
    QFile image(image_path);
    if (!image.open(QIODevice::ReadOnly)) {
        return -1;
    }
    uint32_t blockSize = 0;
    uint64_t blockCount = 0;
    QStringList blockers;
    if (!readApfsRepairGeometry(&image, &blockSize, &blockCount, &blockers)) {
        return -1;
    }
    const ApfsRepairGeometry geometry{blockSize, blockCount};
    QByteArray nxsb(blockSize, '\0');
    if (!readApfsRepairBlock(&image, geometry, kApfsFormatNxsbBlock, &nxsb, &blockers)) {
        return -1;
    }
    ApfsLiveFsChain chain;
    if (!walkLiveFsChain(&image, geometry, le64(nxsb, kApfsNxOmapOidOffset), &chain, &blockers)) {
        return -1;
    }
    QByteArray root(blockSize, '\0');
    if (!readApfsRepairBlock(&image, geometry, chain.volOmapTree, &root, &blockers)) {
        return -1;
    }
    return static_cast<int>(le16(root, kApfsBtreeNodeLevelOffset));
}

int PartitionApfsWriter::readGeneratedExtentRefTreeLevel(const QString& image_path) {
    QFile image(image_path);
    if (!image.open(QIODevice::ReadOnly)) {
        return -1;
    }
    uint32_t blockSize = 0;
    uint64_t blockCount = 0;
    QStringList blockers;
    if (!readApfsRepairGeometry(&image, &blockSize, &blockCount, &blockers)) {
        return -1;
    }
    const ApfsRepairGeometry geometry{blockSize, blockCount};
    QByteArray nxsb(blockSize, '\0');
    if (!readApfsRepairBlock(&image, geometry, kApfsFormatNxsbBlock, &nxsb, &blockers)) {
        return -1;
    }
    ApfsLiveFsChain chain;
    if (!walkLiveFsChain(&image, geometry, le64(nxsb, kApfsNxOmapOidOffset), &chain, &blockers)) {
        return -1;
    }
    QByteArray root(blockSize, '\0');
    if (chain.extentRef == 0 ||
        !readApfsRepairBlock(&image, geometry, chain.extentRef, &root, &blockers)) {
        return -1;
    }
    return static_cast<int>(le16(root, kApfsBtreeNodeLevelOffset));
}

quint64 PartitionApfsWriter::readGeneratedSpacemanCibArrayEntry(const QString& image_path,
                                                                quint64 cib_index) {
    QFile image(image_path);
    if (!image.open(QIODevice::ReadOnly)) {
        return 0;
    }
    uint32_t blockSize = 0;
    uint64_t blockCount = 0;
    QStringList blockers;
    if (!readApfsRepairGeometry(&image, &blockSize, &blockCount, &blockers)) {
        return 0;
    }
    const ApfsRepairGeometry geometry{blockSize, blockCount};
    QByteArray nxsb(blockSize, '\0');
    if (!readApfsRepairBlock(&image, geometry, kApfsFormatNxsbBlock, &nxsb, &blockers)) {
        return 0;
    }
    const QVector<uint64_t> addrs =
        readLiveSpacemanCibArray(&image, geometry, nxsb, cib_index + 1, &blockers);
    return addrs.value(static_cast<qsizetype>(cib_index), 0);
}

QVector<quint64> PartitionApfsWriter::readGeneratedIpFreeQueueGhosts(const QString& image_path) {
    QVector<quint64> ghosts;
    QFile image(image_path);
    if (!image.open(QIODevice::ReadOnly)) {
        return ghosts;
    }
    uint32_t blockSize = 0;
    uint64_t blockCount = 0;
    QStringList blockers;
    if (!readApfsRepairGeometry(&image, &blockSize, &blockCount, &blockers)) {
        return ghosts;
    }
    const ApfsRepairGeometry geometry{blockSize, blockCount};
    QByteArray nxsb(blockSize, '\0');
    if (!readApfsRepairBlock(&image, geometry, kApfsFormatNxsbBlock, &nxsb, &blockers)) {
        return ghosts;
    }
    const ApfsLiveCheckpoint live = readLiveCheckpoint(nxsb);
    const uint64_t fqIpTree =
        findEphemeralPaddrByOid(&image, geometry, live, kApfsFormatFqIpTreeOid, &blockers);
    for (const ApfsFreeQueueEntry& entry :
         parseFreeQueueEntries(&image, geometry, fqIpTree, &blockers)) {
        for (uint64_t i = 0; i < entry.length; ++i) {
            ghosts.append(entry.paddr + i);
        }
    }
    return ghosts;
}

